         public ArmEnvironment(Uri endpoint, string audience)
         {
             Argument.AssertNotNull(endpoint, nameof(endpoint));
             Argument.AssertNotNullOrWhiteSpace(audience, nameof(audience));

             Endpoint = endpoint;
             Audience = audience;
             DefaultScope = $"{Audience}/.default";
         }

